// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getResponseValue } from '@skyramp/skyramp';
import { createUser, deleteUser, createCollection, deleteCollection, getCollectionMembers, createCollectionMember } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Request Body
    const usersPostRequestBody: string = `{
        "email": "testbot-invitee@example.com",
        "name": "Testbot Invitee",
        "password": "testbotpassword123",
        "username": "testbot-invitee"
    }`;

    const usersPostResponse = await createUser(client, URL_localhost, usersPostRequestBody, "testbot-invitee", 201);
    expect(usersPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(usersPostResponse, "response.username"), 'username').toMatch(/^testbot-invitee-/);
    expect(getResponseValue(usersPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    const inviteeId = getResponseValue(usersPostResponse, "response.id");

    // Request Body
    const collectionsPostRequestBody: string = `{
        "description": "testbot invite fixture",
        "name": "Testbot Invite Fixture"
    }`;

    const collectionsPostResponse = await createCollection(client, URL_localhost, collectionsPostRequestBody, 200);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Testbot Invite Fixture");
    expect(getResponseValue(collectionsPostResponse, "response.description"), 'description').toBe("testbot invite fixture");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.ownerId"), 'ownerId').toBeGreaterThan(0);
    const collectionId = getResponseValue(collectionsPostResponse, "response.id");

    const membersGetResponse = await getCollectionMembers(client, URL_localhost, collectionId, 200);
    expect(membersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(membersGetResponse, "response").length, 'member count before invite').toBe(0);
    expect(getResponseValue(membersGetResponse, "response.0"), 'first member before invite').toBeNull();

    // Request Body
    const membersPostRequestBody: string = `{
        "role": "viewer"
    }`;

    // Request Body
    const membersPost1RequestBody: string = `{
        "email": "nobody@nowhere.invalid"
    }`;

    // Request Body
    const membersPost2RequestBody: string = `{
        "email": "testbot-invitee@example.com"
    }`;

    const membersPostResponse = await createCollectionMember(client, URL_localhost, collectionId, membersPostRequestBody, 400);
    expect(membersPostResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(membersPostResponse, "response"), 'error body').toBe("email is required.");

    const membersPost1Response = await createCollectionMember(client, URL_localhost, collectionId, membersPost1RequestBody, 404);
    expect(membersPost1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(membersPost1Response, "response"), 'error body').toBe("User not found.");

    const membersPost2Response = await createCollectionMember(client, URL_localhost, collectionId, membersPost2RequestBody, 201);
    expect(membersPost2Response.statusCode, 'status code').toBe(201);
    expect(getResponseValue(membersPost2Response, "response.userId"), 'invited member userId').toBe(inviteeId);
    expect(getResponseValue(membersPost2Response, "response.collectionId"), 'invited member collectionId').toBe(collectionId);

    const membersGet1Response = await getCollectionMembers(client, URL_localhost, collectionId, 200);
    expect(membersGet1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(membersGet1Response, "response").length, 'member count after invite').toBe(1);
    expect(getResponseValue(membersGet1Response, "response.0.userId"), 'listed member userId').toBe(inviteeId);
    expect(getResponseValue(membersGet1Response, "response.1"), 'second member after invite').toBeNull();

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, URL_localhost, collectionId, 200);
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(collectionId);

    const usersUsersDeleteResponse = await deleteUser(client, URL_localhost, inviteeId, 200);
    expect(usersUsersDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersUsersDeleteResponse, "response"), 'delete user body').toBe("User account and all related data deleted successfully.");
});
